import { test, expect } from '@playwright/test';

test.describe('Search Suggestions Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should highlight matching part of search term in suggestions', async ({ page }) => {
    // Verify search input is visible
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    // Enter search term
    await searchInput.fill('playwright automation');

    // Wait for suggestions to load
    await page.waitForSelector('[data-testid="search-suggestions"]');

    // Verify suggestions container is visible
    const suggestionsContainer = page.getByTestId('search-suggestions');
    await expect(suggestionsContainer).toBeVisible();

    // Verify first suggestion contains highlighted text
    const firstSuggestion = page.getByRole('option', { name: /playwright/i });
    await expect(firstSuggestion).toBeVisible();

    // Verify the highlighted text is present using getByText
    const highlightedText = page.getByText('playwright');
    await expect(highlightedText).toBeVisible();

    // Verify the full suggestion text is visible
    const fullSuggestionText = page.getByText('playwright automation');
    await expect(fullSuggestionText).toBeVisible();

    // Verify the highlight spans the matching part
    const highlightSpan = page.locator('[data-testid="highlight-span"]');
    await expect(highlightSpan).toBeVisible();
    await expect(highlightSpan).toContainText('playwright');

    // Verify the suggestion has a hover effect
    await firstSuggestion.hover();
    await expect(firstSuggestion).toHaveCSS('background-color', 'rgb(240, 240, 255)');
  });

  test('should not highlight when no match is found', async ({ page }) => {
    // Enter non-existent search term
    const searchInput = page.getByPlaceholder('Search...');
    await searchInput.fill('xyz123nonexistentterm');

    // Wait for suggestions to load
    await page.waitForSelector('[data-testid="search-suggestions"]');

    // Verify suggestions container is visible
    const suggestionsContainer = page.getByTestId('search-suggestions');
    await expect(suggestionsContainer).toBeVisible();

    // Verify no suggestions are displayed
    const suggestionOptions = page.getByRole('option');
    const count = await suggestionOptions.count();
    expect(count).toBe(0);

    // Verify no highlight span exists
    const highlightSpan = page.locator('[data-testid="highlight-span"]');
    await expect(highlightSpan).not.toBeVisible();

    // Verify no highlight class is applied to suggestions
    const suggestionItems = page.locator('[data-testid="suggestion-item"]');
    const hasHighlightClass = await suggestionItems.first().evaluate((el) => el.classList.contains('highlight'));
    expect(hasHighlightClass).toBe(false);

    // Verify search input retains the full text
    await expect(searchInput).toHaveValue('xyz123nonexistentterm');
  });
});
